(() => {
  const Z=window.Zucco,{state,icon:I,avatar:A,badge:B,btn:BT,money:M,escape:E}=Z;
  const METHODS=Object.freeze(['Cash','Payme / Click','Terminal']);
  const methodIcon=method=>method==='Cash'?'cash':method==='Terminal'?'card':'wallet';
  function metric(label,value,glyph,tone,note){return `<section class="metric" data-component="FinanceKPI"><div class="metric-top"><span>${label}</span><span class="metric-icon ${tone}">${I(glyph)}</span></div><p class="metric-value ${tone==='danger'?'text-danger':''}">${M(value)}<small>UZS</small></p><p class="metric-foot">${note}</p></section>`;}
  Z.financeRows=()=>state.transactions.filter(t=>(state.financeTab==='all'||t.kind===state.financeTab)&&(t.name+' '+t.id+' '+t.course).toLowerCase().includes(state.financeSearch.toLowerCase())).map(t=>`<tr><td><div class="row gap-12"><span class="transaction-icon ${t.kind==='income'?'success':'danger'}">${I(t.kind==='income'?'arrowDown':'arrowUp')}</span><div><div class="table-primary">${E(t.name)}</div><div class="table-secondary">${E(t.course)}</div></div></div></td><td><span class="payment-method">${I(methodIcon(t.method))}${E(t.method)}</span></td><td>${B(t.kind==='income'?'Received':'Expense',t.kind==='income'?'success':'')}</td><td class="mono caption">${t.time}</td><td class="text-end mono ${t.kind==='income'?'text-success':'text-danger'}"><strong style="font-weight:500">${t.kind==='income'?'+':'−'}${M(t.amount)}</strong></td><td><button type="button" class="receipt-link mono" data-action="receipt:${t.id}">${I('receipt')}${t.id}</button></td></tr>`).join('')||`<tr><td colspan="6"><div class="empty-state">${I('search')}No matching transactions. Try a different name or receipt number.</div></td></tr>`;
  Z.renderers[Z.ROUTES.FINANCE]=()=>Z.heading('Financial desk','A clear picture of every payment, balance, and expense.',BT('Record expense','record-expense','arrowUp')+BT('Accept Payment','payment','plus','primary'))+
    `<div class="metrics">${metric("Today's Cash Income",state.cashIncome,'cash','success','<span class="positive">↑ 18.4%</span> vs. yesterday · 3 cash payments')}${metric('Terminal / Card',state.cardIncome,'card','accent','3 payments · Payme, Click & terminal')}${metric('Pending Tuition Debt',state.pendingDebt,'alert','danger','<span class="negative">24 students</span> with an outstanding balance')}${metric("Today's Expenses",state.expenses,'arrowUp','','2 expenses · 2 Nov, 2026')}</div>
    <div class="view-tabs finance-tabs"><button type="button" class="view-tab ${state.financeTab==='all'?'active':''}" data-action="finance-tab:all" aria-pressed="${state.financeTab==='all'}">All transactions<span class="count">${state.transactions.length}</span></button><button type="button" class="view-tab ${state.financeTab==='income'?'active':''}" data-action="finance-tab:income" aria-pressed="${state.financeTab==='income'}">Income</button><button type="button" class="view-tab ${state.financeTab==='expense'?'active':''}" data-action="finance-tab:expense" aria-pressed="${state.financeTab==='expense'}">Expenses</button><div class="grow"></div><span class="caption" style="padding-bottom:12px">Cashier · Yunusobod branch</span></div>
    <div class="toolbar"><label class="input-search" style="width:290px">${I('search')}<input type="search" id="finance-search" placeholder="Search student or receipt…" value="${E(state.financeSearch)}" aria-label="Search transactions"></label><label class="row"><span class="sr-only">Transaction date</span><input type="date" id="finance-date" class="input" value="2026-11-02"></label><div class="toolbar-spacer"></div>${BT('Export transactions','export-finance','download')}</div>
    <div class="panel table-scroll"><table class="compact-table finance-table"><thead><tr><th style="width:30%">Student / description</th><th style="width:16%">Payment method</th><th style="width:12%">Status</th><th style="width:9%">Time</th><th class="text-end" style="width:17%">Amount, UZS</th><th style="width:16%">Receipt</th></tr></thead><tbody id="transaction-rows">${Z.financeRows()}</tbody></table><div class="table-footer"><span>${state.transactions.length} transactions today</span><div class="row gap-12"><span>All amounts in UZS</span><span class="badge success">${I('checkCircle')}Balanced</span></div></div></div>
    <div class="finance-banner"><span class="row">${I('alert')}<span><strong>24 students have overdue tuition.</strong> Review balances and send a payment reminder.</span></span>${BT('Review outstanding debt','review-debt','arrow','small')}</div>`;
  const studentDebt=()=>{const student=Z.platform?.students.find(s=>s.name===state.paymentStudent);return student?Z.studentBalance(student):state.paymentStudent==='Azizbek Karimov'?state.balance:-450000;};
  Z.paymentSummary=()=>{const after=studentDebt()+Number(state.amount||0);return `<div class="row between"><span class="muted">Current balance</span><strong class="mono ${studentDebt()<0?'text-danger':'text-success'}">${Z.signedMoney(studentDebt())} UZS</strong></div><div class="row between"><span class="muted">Payment amount</span><strong class="mono">+${M(Number(state.amount)||0)} UZS</strong></div><div class="row between total"><span>Balance after payment</span><strong class="mono ${after<0?'text-danger':'text-success'}">${Z.signedMoney(after)} UZS</strong></div>`;};
  Z.renderPayment=()=>`<form id="payment-form"><header class="drawer-top"><div><h2 id="payment-title">Accept payment</h2><p>Record a tuition payment to the student balance.</p></div><button type="button" class="icon-btn" aria-label="Close payment drawer" data-action="close-payment">${I('close')}</button></header><div class="drawer-body">
    <div><label class="field-label" for="payment-student">Student <span class="required">*</span></label><div class="selected-student">${A(state.paymentStudent)}<div class="grow"><select class="student-option" id="payment-student" name="student" required>${(Z.platform?.students||state.attendance).map(s=>`<option ${s.name===state.paymentStudent?'selected':''}>${E(s.name)}</option>`).join('')}</select><p class="table-secondary">#ZU-0248 · IELTS Foundation</p></div></div><p class="student-balance-hint">${I('alert')}Outstanding tuition: ${M(Math.max(0,-studentDebt()),true)}</p></div>
    <div><span class="field-label" id="method-label">Payment method <span class="required">*</span></span><div class="payment-tabs" role="group" aria-labelledby="method-label">${METHODS.map(method=>`<button type="button" class="method-tab ${state.paymentMethod===method?'active':''}" data-action="payment-method:${method}" aria-pressed="${state.paymentMethod===method}">${I(methodIcon(method))}${method}</button>`).join('')}</div></div>
    <div><label class="field-label" for="payment-amount">Amount <span class="required">*</span></label><div class="amount-wrap"><input type="number" id="payment-amount" name="amount" required min="1" step="1" max="999999999" class="input" value="${state.amount}" inputmode="numeric" aria-describedby="amount-error"><span class="amount-unit">UZS</span></div><div class="quick-amounts">${[300000,600000,1000000].map(v=>`<button type="button" data-action="payment-amount:${v}">${M(v)}</button>`).join('')}</div><p id="amount-error" class="amount-error" role="alert" hidden>Enter a payment amount greater than 0 UZS.</p></div>
    <div><label class="field-label" for="payment-note">Payment note</label><input type="text" class="input field-control" id="payment-note" name="note" maxlength="160" value="${E(state.paymentNote||'November tuition')}"><p class="payment-allocation">${I('book')}Allocated to IELTS Foundation · IF-09 · November 2026</p></div>
    <div class="payment-summary" id="payment-summary">${Z.paymentSummary()}</div><label class="print-row"><span class="switch"><input type="checkbox" id="print-receipt" name="print" ${state.printReceipt===false?'':'checked'} aria-label="Print receipt"><span class="switch-track"><span class="switch-thumb"></span></span></span><span class="grow"><span class="table-primary">Print receipt</span><span class="table-secondary" style="display:block">A receipt will be prepared after confirmation.</span></span>${I('print')}</label>
    </div><footer class="drawer-footer"><button class="btn primary wide" type="submit">${I('checkCircle')}Confirm payment · ${M(Number(state.amount)||0)} UZS</button><p>Recorded to Yunusobod branch · Cashier: Asilbek B.</p></footer></form>`;
  Z.openPayment=()=>{state.amount=600000;state.paymentStudent='Azizbek Karimov';state.paymentMethod='Cash';document.getElementById('payment-dialog').innerHTML=Z.renderPayment();document.getElementById('payment-dialog').showModal();};
  Z.recordPayment=form=>{const values=new FormData(form),amount=Number(values.get('amount'));if(!Number.isFinite(amount)||amount<=0||!Number.isInteger(amount)){const error=document.getElementById('amount-error');error.hidden=false;document.getElementById('payment-amount').focus();return;}
    const name=String(values.get('student')),previousBalance=studentDebt();const receipt=`RCPT-${2049+state.transactions.filter(t=>t.id.startsWith('RCPT-20')&&Number(t.id.slice(5))>=2049).length}`;
    state.transactions.unshift({id:receipt,name,course:'IELTS Foundation · IF-09',amount,method:state.paymentMethod,time:'10:48',kind:'income'});
    if(name==='Azizbek Karimov')state.balance+=amount;
    else {const student=Z.platform?.students.find(s=>s.name===name);if(student)student.balance+=amount;}
    if(state.paymentMethod==='Cash')state.cashIncome+=amount;else state.cardIncome+=amount;
    state.pendingDebt=Math.max(0,state.pendingDebt-Math.min(amount,Math.max(0,-previousBalance)));
    const print=values.get('print')==='on';document.getElementById('payment-dialog').close();Z.render();Z.toast(`Payment received · ${M(amount,true)} · ${receipt}`);if(print)Z.showReceipt(receipt);
  };
  Z.showReceipt=id=>{const t=state.transactions.find(t=>t.id===id);if(!t)return;Z.actionDialog(`<div class="dialog-body receipt"><div class="dialog-title-row"><h2 id="action-title">Payment receipt</h2>${BT('','close-action','close','ghost small')}</div><div class="receipt-mark">zucco</div><p>Zucco Academy · Yunusobod branch</p><div class="receipt-total ${t.kind==='income'?'text-success':'text-danger'}">${M(t.amount)} <span class="caption">UZS</span></div><div class="detail-row"><span>Receipt number</span><strong>${t.id}</strong></div><div class="detail-row"><span>${t.kind==='income'?'Student':'Description'}</span><strong>${E(t.name)}</strong></div><div class="detail-row"><span>Method</span><strong>${t.method}</strong></div><div class="detail-row"><span>Date & time</span><strong>2 Nov, 2026 · ${t.time}</strong></div><div class="detail-row"><span>Cashier</span><strong>Asilbek B.</strong></div></div><div class="dialog-footer">${BT('Done','close-action','check','primary')}</div>`);};
})();
